WITH metrics AS (SELECT id, store_name, city, sqft, LAG(sqft) OVER (PARTITION BY city ORDER BY opened_date, id) AS prev_sqft, ROW_NUMBER() OVER (PARTITION BY city ORDER BY opened_date, id) AS seq_no FROM stores), kept AS (SELECT s.* FROM metrics s WHERE NOT EXISTS (SELECT 1 FROM store_sales x WHERE x.store_id = s.id AND x.revenue > 3400)), base AS (SELECT *, CONCAT(city, ' - ', store_name) AS city_store_name, GREATEST(sqft, seq_no) AS greatest_sqft_seq_no FROM kept WHERE city = 'Bangkok'), cleaned AS (SELECT id, store_name, city, sqft, seq_no, greatest_sqft_seq_no, prev_sqft / NULLIF(greatest_sqft_seq_no, 0) AS prev_sqft_per_greatest_sqft_seq_no, sqft - prev_sqft AS sqft_minus_prev_sqft FROM base WHERE greatest_sqft_seq_no <= 60) SELECT seq_no, city, ROUND(SUM(sqft) / NULLIF(COUNT(CASE WHEN city = 'Singapore' THEN 1 END), 0), 2) AS sqft_per_singapore, BIT_OR(sqft) AS sqft_bit_or, SUM(CASE WHEN city = 'Tokyo' THEN seq_no ELSE 0 END) AS tokyo_seq_no, ROUND(AVG(greatest_sqft_seq_no), 2) AS avg_greatest_sqft_seq_no, PERCENTILE_APPROX(sqft_minus_prev_sqft, 0.9) AS sqft_minus_prev_sqft_p90, SUM(greatest_sqft_seq_no) FILTER (WHERE city = 'Berlin') AS berlin_total_greatest_sqft_seq_no FROM cleaned GROUP BY seq_no, city HAVING sqft_bit_or > 1 ORDER BY tokyo_seq_no DESC;
